INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('logement . type','logement','Dans quel type de logement vivez-vous principalement ?','🏠','CHOIX_UNIQUE','{"options":["maison","appartement","autre"],"note":"En 2018, l’habitat individuel représente 56 % des logements ([Source INSEE](https://www.insee.fr/fr/statistiques/3676693?sommaire=3696937)) : il est majoritaire parmi les résidences principales comme parmi les résidences secondaires et logements occasionnels. Après avoir progressé entre 1999 et 2008 sa part recule légèrement, car le nombre de logements collectifs augmente plus vite que celui des logements individuels du fait des évolutions récentes de la construction neuve.\nNotons qu''il s''agit d''une proportion de logements ; or on peut s''attendre (à vérifier) à ce que les maisons contiennent davantage de gens en moyenne que les appartements, ce qui renforce le choix de la valeur par défaut.\n"}'::jsonb,1,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('logement . surface','logement','Quelle est la surface de votre logement ?','📏','NOMBRE','{"min":1,"max":999,"defaultValue":{"arrondi":"1 décimale","variations":[{"si":"logement . est un appartement","alors":"parc français . surface moyenne appartement"},{"si":"logement . est une maison","alors":"parc français . surface moyenne maison"},{"si":"logement . est un autre logement","alors":"20 m2"},{"sinon":"parc français . surface moyenne"}]},"unit":"m2","description":"Si vous êtes en colocation, chez vos parents, ou habitat partagé, renseignez la surface totale du logement. Le nombre de personnes sera pris en compte par la suite.\n","note":"Valeur par défaut obtenue dans [ce jeu de données du Ceren et SDES](https://www.statistiques.developpement-durable.gouv.fr/consommation-denergie-par-usage-du-residentiel).\n\n> Les logements ont une surface moyenne d’environ 91 m2.\n\n> Si vous vivez dans un logement original, par exemple un camping-car / un camion / une péniche, renseignez simplement les m² de ce logement.\n","suggestions":{"studio":30,"1 chambre":50,"2 chambres":70,"3 chambres":100,"Plus de 4 chambres":150}}'::jsonb,2,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('logement . propriétaire','logement','Êtes-vous propriétaire ou locataire de votre logement ?','🔑','CHOIX_UNIQUE','{"options":["propriétaire","locataire","hébergé"],"defaultValue":"''propriétaire''","note":"En tant que locataire, il est évidemment délicat de faire les investissements qui améliorent l''empreinte du logement : isolation, changement de source d''énergie sont impossibles sauf à tomber sur un propriétaire particulièrement conciliant.\n\nPourtant, la loi pourrait dès 2023 être un soutien de poids : les passoires thermiques [seront interdites à la location](https://www.gouvernement.fr/interdiction-a-la-location-des-logements-avec-une-forte-consommation-d-energie-des-2023), forçant les propriétaires à lancer des travaux substentiels.\n"}'::jsonb,3,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('logement . habitants','logement','Combien de personnes vivent chez vous ?','👥','NOMBRE','{"min":1,"max":30,"defaultValue":"habitants . moyen","description":"Cette information permet de rapporter les consommations collectives du foyer (mobilier, chauffage, etc.) à votre part individuelle.\n\n> 💡 Si vous vivez seul, répondez **1**, si un membre de votre foyer n''y habite pas tous les jours, vous pouvez rentrer quelque-chose comme **1,5**.\n","suggestions":{"j''habite seul":1,"deux personnes":2,"parents et 2 enfants":4,"famille nombreuse":6}}'::jsonb,4,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('logement . chauffage','logement','Qu''utilisez vous pour la cuisson, l''eau chaude et chauffer ou climatiser votre logement ?','🔥','CHOIX_MULTIPLE','{"options":["électricité . présent","gaz . présent","PAC . présent","bois . présent","réseau de chaleur . présent","bouteille gaz . présent","fioul . présent","citerne propane . présent","chauffe eau solaire . présent","logement . climatisation . présent","logement . électricité . photovoltaique . présent","aucun . présent"],"description":"**Ne sélectionnez pas \"électricité\"** si elle alimente seulement vos appareils électriques quotidiens (éclairage, électroménager, etc.).\n"}'::jsonb,5,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('logement . chauffage . précision consommation . ressenti','logement','Quel est votre ressenti sur le confort thermique de votre logement en hiver ?','🌡️','CHOIX_UNIQUE','{"options":["passoire thermique","moyen","confortable"],"defaultValue":"''moyen''","description":"Si vous vivez dans une région où il n''est pas nécessaire de chauffer, transposez la question sur le ressenti en été, avec la climatisation par exemple.\n","note":"L''idée est d''utiliser cette variable pour pondérer les consommations d''un logement moyen estimées via les consommations réelles du parc français, en considérant un DPE moyen en France à D. Ainsi, on peut ajuster la valeur moyenne de consommation avec un saut de classe de D vers A ou de D vers G selon le ressenti de l''utilisateur.\n"}'::jsonb,6,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('transport . voiture . utilisateur','transport','Vous arrive t-il de vous déplacer en voiture (en tant que passager ou conducteur) ?','🚗','CHOIX_UNIQUE','{"options":["propriétaire","régulier non propriétaire","non régulier","jamais"],"description":"Choisissez ce qui correspond à la majorité de vos trajets.\n","note":"Deux données sont importantes dans le cadre du calcul de l''empreinte liée à la construction :\n\n- L''usage ou non d''un même véhicule pour tous les kilomètres parcourus (si non : on vous attribue un véhicule \"moyen\")\n- La propriété ou non dudit véhicule s''il s''agit toujours du même\n\nNous avons fait le choix d''attribuer l''empreinte de construction au pro-rata des kilomètres parcourus. Mais cette approche avait deux défauts :\n\n- Elle était extrêmement avantageuse pour les petits rouleurs, alors que leur véhicule qui roule moins peut s''user plus vite (un moteur a besoin de tourner régulièrement) et donc avoir une durée de vie inférieure.\n- Elle ne permettait pas de valoriser l''engagement de ne pas disposer de son propre véhicule, et de pratiquer à la place l''autopartage, ou la location ponctuelle (car l''empreinte de construction était la même, que l''on soit propriétaire ou non).\n\n> Pour pallier ces deux problèmes, et mieux représenter qu''un véhicule possédé mais sous-utilisé s''use plus vite et mérite une empreinte de construction plus importante, **nous appliquons un seuil pour la partie construction de l''empreinte, pour les propriétaires**.\n"}'::jsonb,7,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('transport . voiture . km','transport','Quelle distance parcourez-vous à l''année en voiture ?','⛽','NOMBRE','{"min":1,"max":99999,"defaultValue":"km annuels moyen","unit":"km","description":"Ne comptez que les kilomètres de déplacement personnel (courses, loisirs, famille, etc.) et de déplacement domicile-travail.\n\nSi une mission professionnelle vous amène à vous déplacer plus loin que votre lieu de travail habituel, ne comptez pas ici les km concernés.\n","dependances":[{"key":"transport . voiture . utilisateur","value":["propriétaire","régulier non propriétaire","non régulier"],"type":"IN"}],"suggestions":{"vacances":2000,"10 km / jour":3600,"1000 km / mois":12000,"20000 km / an":20000}}'::jsonb,8,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('transport . voiture . motorisation','transport','Quel type de voiture utilisez-vous ?','🔧','CHOIX_UNIQUE','{"options":["thermique","électrique","hybride non rechargeable","hybride rechargeable"],"defaultValue":"''thermique''","description":"💡 **Si vous utilisez plusieurs voitures (par exemple dans le cas où vous n''en possédez pas une), choisissez la réponse la plus représentative de votre usage.**","dependances":[{"key":"transport . voiture . utilisateur","value":["propriétaire","régulier non propriétaire"],"type":"IN"}]}'::jsonb,9,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('transport . mobilité douce','transport','Parmi ces modes de déplacement, lesquels utilisez-vous ?','🚲','CHOIX_MULTIPLE','{"options":["vélo . présent","vae . présent","autres véhicules à moteur . présent","aucun . présent"],"description":"Si vous possédez un vélo-cargo disposant d''une assistance électrique, classez-le dans la catégorie VAE ! Sinon, il est du côté des vélos \"classiques\".\n"}'::jsonb,10,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('transport . avion . usager','transport','Avez-vous pris l''avion au moins une fois ces 3 dernières années ?','✈️','BOOLEEN','{"options":["oui","non"]}'::jsonb,11,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('transport . avion . moyen courrier . heures de vol','transport','Sur une année, combien d''heures voyagez-vous sur des vols entre 2 et 6h (moyen-courrier) ?','🕒','NOMBRE','{"min":0,"max":600,"defaultValue":"durée moyenne","unit":"h","description":"Comptez les heures que vous avez passées dans un avion pour des trajets entre 2h et 6h.\n\nSi vous avez fait un trajet de 8h en deux vols de 4h, ils sont bien à comptabiliser ici.\n\n💡 Ne comptez que les km de déplacement personnel.\n","note":"La caractérisation \"moyen courrier\" par le temps de trajet est donnée par la règle `court courrier . durée max`=2.17h et `moyen courrier . durée max` = 6.48h.","dependances":[{"key":"transport . avion . usager","value":"oui","type":"EQUAL"}],"suggestions":{"Aucun":0,"Paris ⇄ Copenhague":4,"Paris ⇄ Alger":5,"Paris ⇄ Athènes":6,"Paris ⇄ Liban":8}}'::jsonb,12,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('alimentation . plats','alimentation','Choisissez les 14 repas (déjeuners et dîners) de votre semaine-type','🍽️','COMPTEUR','{"options":["végétalien . nombre","végétarien . nombre","viande blanche . nombre","viande rouge . nombre","poisson gras . nombre","poisson blanc . nombre"],"description":"Choisissez les plats qui représentent votre semaine type. A priori, vous en aurez 14 : 7 déjeuners et 7 dîners. Mais vous pouvez néanmoins en saisir moins, ou plus.\n\nLes menus ont été travaillés pour être représentatifs des consommations alimentaires des français.\n","note":"Pour le moment, nous proposons 6 repas types pour 6 régimes différents. Il a été choisi de limiter la granularité du modèle via 6 menus représentatifs\ndes régimes associés pour simplifier l''estimation de l''empreinte du poste alimentation pour l''utilisateur\n(les spécificités de l''alimentation de chacun pourraient donner lieu à un simulateur complet dédié à l''alimentation).\n\nIls ne sont pas directement basés sur les régimes de la Base Empreinte, [documentés par l''ADEME](https://www.bilans-ges.ademe.fr/documentation/UPLOAD_DOC_FR/index.htm?repas.htm), jugés obsolètes (peu exhaustifs, FE non issus d''Agribalyse).\n\nEn revanche, nous avons travaillé sur des repas types basés sur une consolidation multi-facteurs (quantité totale d''aliments consommés, quantité de viande et poisson consommés, apports énergétiques, empreinte carbone moyenne d''un repas)\nbasé sur les données de [l''étude INCA 3](https://www.anses.fr/fr/system/files/NUT2014SA0234Ra.pdf), permettant de se rapprocher du régime moyen d''un Français.\n\n💡 Vous trouverez la documentation complète dans [notre wiki](https://accelerateur-transition-ecologique-ademe.notion.site/Empreinte-des-repas-NGC-377d2143f3a14b558ab2c8e0426d2e23).\n\n🧮 Le calcul détaillé est [disponible ici](https://docs.google.com/spreadsheets/d/1L3p1m2jtbSK7f3i9AYvWIHntXhI_IiVIY9RM6-IxTb8/edit?gid=925636017#gid=925636017) sous forme de tableur.\n","min":0,"max":14,"suggestions":{"végétalien":{"végétalien . nombre":14,"végétarien . nombre":0,"viande blanche . nombre":0,"viande rouge . nombre":0,"poisson gras . nombre":0,"poisson blanc . nombre":0},"végétarien":{"végétalien . nombre":3,"végétarien . nombre":11,"viande blanche . nombre":0,"viande rouge . nombre":0,"poisson gras . nombre":0,"poisson blanc . nombre":0},"peu de viande":{"végétalien . nombre":1,"végétarien . nombre":7,"viande blanche . nombre":4,"viande rouge . nombre":0,"poisson gras . nombre":1,"poisson blanc . nombre":1},"viande chaque jour":{"végétalien . nombre":0,"végétarien . nombre":0,"viande blanche . nombre":6,"viande rouge . nombre":6,"poisson gras . nombre":1,"poisson blanc . nombre":1}}}'::jsonb,13,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('alimentation . boisson . eau en bouteille . consommateur','alimentation','Buvez-vous votre eau en bouteille ?','💧','BOOLEEN','{"options":["oui","non"],"description":"Nous cherchons à capter ici si votre consommation d''eau en bouteille est très régulière : cochez oui seulement si vous buvez de l''eau en bouteille chaque jour.\n\n> La consommation d''eau du robinet (pour tous usages) a une empreinte climat négligeable. Nous ne posons donc pas la question !\n","note":"Les français boivent en moyenne entre 100 et 150 litres d''eau en bouteille par an [source](https://www.planetoscope.com/consommation-eau/854-litres-d-eau-en-bouteille-vendus-en-france.html), soit environ un tiers de nos besoins de 1-1,5l par jour [source](https://www.mangerbouger.fr/Le-Mag/Bien-etre/L-eau-indispensable-a-notre-bonne-sante).\n\nNous avons considéré que la valeur par défaut était donc \"non\".\n"}'::jsonb,14,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('divers . numérique . appareils','divers','Quels appareils numériques possédez-vous ?','💻','COMPTEUR','{"options":["téléphone . nombre","TV . nombre","ordinateur portable . nombre","ordinateur fixe . nombre","tablette . nombre","enceinte bluetooth . nombre","console de salon . nombre","console portable . nombre","imprimante . nombre","aucun . présent"],"description":"L''empreinte des **appareils partagés** au niveau du foyer (télévision ou ordinateur fixe par exemple) est **divisée par le nombre d''habitants**.\n\nL''empreinte des **appareils individuels** (comme le téléphone portable) vous est **attribuée personnellement**.\n","note":"Cette catégorie est un peu particulière au niveau de l''amortissement. En effet, à l''inverse de l''ameublement ou l''on considère que tout est partagé au sein du foyer, ici, certains appareils sont partagés alors que d''autres sont considérés comme étant individuels.\n\nAinsi nous avons défini arbitrairement les appareils individuels (téléphone, tablette, enceinte bluetooth, ordinateur portable, console portable) et collectifs (TV, ordinateur fixe, console de salon).\n\nPour le moment, nous ne considérons pas la fin de vie des appareils ici mais dans le poste \"déchets\".\n\nSelon [le baromètre du numérique 2025](https://www.arcep.fr/uploads/tx_gspublication/barometre-du-numerique_edition_2025_RAPPORT_mars2025.pdf), un foyer français possède en moyenne 9,6 équipements numériques avec écran, soit 4,4 équipements par personne. Selon ce même rapport, parmi ces 9,6 équipements, 1,8 sont inutilisés, ce qui peut laisser penser que les saisies seront souvent sous-estimées.\n","suggestions":{"vie sans écran":{"téléphone . nombre":1,"TV . nombre":0,"ordinateur portable . nombre":1,"ordinateur fixe . nombre":0,"tablette . nombre":0,"enceinte bluetooth . nombre":1,"console de salon . nombre":0,"console portable . nombre":0,"imprimante . nombre":0},"vie connectée":{"téléphone . nombre":1,"TV . nombre":2,"ordinateur portable . nombre":1,"ordinateur fixe . nombre":1,"tablette . nombre":1,"enceinte bluetooth . nombre":1,"console de salon . nombre":0,"console portable . nombre":1,"imprimante . nombre":1},"gamer":{"téléphone . nombre":1,"TV . nombre":3,"ordinateur portable . nombre":1,"ordinateur fixe . nombre":1,"tablette . nombre":1,"enceinte bluetooth . nombre":1,"console de salon . nombre":2,"console portable . nombre":1,"imprimante . nombre":1}}}'::jsonb,15,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('divers . textile . volume','divers','Pour quelle raison achetez-vous de nouveaux vêtements ?','🛍️','CHOIX_UNIQUE','{"options":["minimum","renouvellement occasionnel","accro au shopping"],"description":"L''achat \"coup-de-coeur\" peut-être vu comme l''achat d''une pièce à la mode, tendance. L''achat par besoin est un achat réfléchi qui se fait par nécessité : remplacement de vêtements usés ou abîmés, ou nouvel usage (vous vous inscrivez au football et vous n''avez ni crampons ni short).\n"}'::jsonb,16,true) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('logement . âge','logement','Quel est l''âge de votre logement ?','🏚️','CHOIX_UNIQUE','{"options":["très récent","récent","ancien"],"defaultValue":"''récent''","description":"Un petit doute ? La date de construction de votre logement apparaît sans doute sur votre contrat d''assurance.\n","note":"Il n''est pas évident de trouver un \"chiffre moyen\" pour l''âge des logements en France. Néanmoins, l''[INSEE](https://www.insee.fr/fr/statistiques/7632072?geo=EPCI-242900553&sommaire=7632098) fournit, jusqu''à 2018, les tranches d''ancienneté des résidences principales en France métropolitaine, à savoir :\n\n| Période        | Répartition (%) |\n|----------------|----------------|\n| Avant 1919     | 7,2            |\n| 1919–1945      | 5,4            |\n| 1946–1970      | 15,7           |\n| 1971–1990      | 32,0           |\n| 1991–2005      | 21,3           |\n| 2006–2017      | 18,4           |\n\nEn affectant une tranche médiane pour chaque période, on obtient un âge moyen pondéré d''environ 41 ans. En considérant que le parc de logements s''agrandit chaque année tout en vieillissant de manière générale, on peut arrondir cette valeur à 45 ans pour 2025.\n\nNB: Pour Paris, [cette carte](https://www.comeetie.fr/galerie/BatiParis) interactive est fascinante si la question de l''âge de ses logements vous intéresse.\n"}'::jsonb,17,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('logement . vacances','logement','Comment êtes-vous hébergé pour vos week-ends, vos vacances ?','🏖️','CHOIX_MULTIPLE','{"options":["hotel . présent","camping . présent","auberge de jeunesse . présent","locations . présent","famille ou amis . présent","échange . présent","résidence secondaire . présent","croisière . présent","aucun . présent"],"description":"Renseignez ici les différents types de logement que vous occupez pour vos voyages (à motif **personnel**).\n\n> 💡 Si vous ne partez jamais en week-end ou en vacances, vous pouvez cliquer sur \"aucun\" juste en dessous de cette question, puis \"Suivant\".\n","note":"### Qu''entend-on par \"nuitées hors logement\" dans Nos Gestes Climat?\n\n  - Hôtel ou chambre d''hôtes\n  - Emplacement en camping\n  - Auberge de jeunesse\n  - Locations meublées\n  - Famille ou amis\n  - Échange de maison\n  - Résidence secondaire\n  - Bateau de croisière\n\nSont donc exclues les nuits en hôtel pour **raisons professionnelles**.\n\n### Quelles données utilisons nous ?\n\nUne étude ADEME sur le secteur du tourisme en France sortie fin 2024, [Bilan des émissions de gaz à effet de serre du secteur du tourisme en France](https://librairie.ademe.fr/changement-climatique/7637-bilan-des-emissions-de-gaz-a-effet-de-serre-du-secteur-du-tourisme-en-france-en-2022.html), fournit divers chiffres relatifs aux nuitées des logements touristiques. Néanmoins, nous manquons d''hypothèses d''arrière plan et ne sommes pas en mesure de \"vérifier\" leur contenu pour éviter le double comptage par exemple. Malheureusement, le service en charge de l''étude n''a pas pu nous fournir de données plus précises. Nous avons donc retravaillé certains mode d''hébergement à partir de données plus transparentes lorsque c''était possible.\n\n### Nos hypothèses en bref\n\n- Pour l''empreinte d''une nuit au sein de sa famille ou chez des amis, l''empreinte est aujourd''hui indirectement comptée dans l''empreinte des accueillants.\n\n- Pour les hôtels et les chambres privées / chambres d''hôtes, nous considérons un facteur d''émission commun pour le moment.\n\n- L''empreinte des logements de vacances (hors auberge de jeunesse et croisière) est divisée par le nombre d''habitants du logement. C''est une hypothèse forte car on peut facilement imaginer que le famille / foyer ne voyage pas toujours au complet ! Néanmoins, on considère tout de qu''une famille composée de plus de 4 personnes prendra 2 chambres.\n"}'::jsonb,18,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('alimentation . petit déjeuner . type','alimentation','Quel petit-déjeuner vous correspond le plus ?','🥐','CHOIX_UNIQUE','{"options":["continental","lait céréales","britannique","végétalien","aucun"],"defaultValue":"''continental''","description":"Si vous hésitez, choisissez celui qui se rapproche le plus de vos habitudes.\n\nVotre consommation de jus de fruits / café / thé / chocolat chaud sera comptabilisée dans les questions dédiées aux boissons.\n"}'::jsonb,19,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('alimentation . local . consommation','alimentation','À quelle fréquence consommez-vous des produits locaux ?','🌍','CHOIX_UNIQUE','{"options":["jamais","parfois","souvent","oui toujours"],"defaultValue":"''jamais''","description":"Si comme 40 % de français.e.s, vous cultivez vos fruits et légumes, bravo ! \nDifficile toutefois d’en estimer l’empreinte, de par la diversité des pratiques et du degré d’autonomie alimentaire.\n","note":"Voir détail de l''approche de calcul [ici](http://nosgestesclimat/documentation/alimentation/local/part-locale)"}'::jsonb,20,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('alimentation . de saison . consommation','alimentation','À quelle fréquence consommez vous des fruits et légumes de saison ?','🍓','CHOIX_UNIQUE','{"options":["jamais","parfois","souvent","oui toujours"],"defaultValue":"''jamais''","note":"Voir détail de l''approche de calcul [ici](http://nosgestesclimat/documentation/alimentation/de-saison/pourcentage-saisonable)"}'::jsonb,21,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('alimentation . boisson . chaude','alimentation','Quelle est votre consommation de boissons chaudes par jour (en nombre de tasses) ?','☕','COMPTEUR','{"options":["café . nombre","thé . nombre","chocolat chaud . nombre","chicorée . nombre","aucun . présent"],"description":"Renseignez ici ce que vous consommez lors d''une journée type (dont le petit-déjeuner). Vos consommations occasionnelles sont considérées comme négligeables.\n\nSi vous buvez du chocolat chaud, nous vous demanderons le type de lait dans une autre question !\n","suggestions":{"un café":{"café . nombre":1,"thé . nombre":0,"chocolat chaud . nombre":0,"chicorée . nombre":0},"beaucoup de café":{"café . nombre":4,"thé . nombre":0,"chocolat chaud . nombre":0,"chicorée . nombre":0},"un café et un thé":{"café . nombre":1,"thé . nombre":1,"chocolat chaud . nombre":0,"chicorée . nombre":0},"un chocolat chaud":{"café . nombre":0,"thé . nombre":0,"chocolat chaud . nombre":1,"chicorée . nombre":0}}}'::jsonb,22,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('alimentation . boisson . sucrées . litres','alimentation','Quelle est votre consommation par semaine de sodas, jus de fruits, etc. ?','🥤','NOMBRE','{"min":0,"max":20,"defaultValue":1,"unit":"l/semaine","note":"La consommation de sodas et boissons sucrées en France est en moyenne de 50,9 litres par habitant ([source](https://www.sante-et-nutrition.com/consommation-soda-france/)) soit à peu près 1 litre par semaine.","suggestions":{"nulle":0,"ponctuelle":1,"quotidienne":3}}'::jsonb,23,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('alimentation . boisson . alcool . litres','alimentation','Quelle est votre consommation par semaine d''alcool (vin, bière, etc.) ?','🍷','NOMBRE','{"min":0,"max":20,"defaultValue":1.5,"unit":"l/semaine","note":"La consommation d''alcool en France est de 79,6 litres d''alcool, tous alcools confondus, soit à peu près 1,5 litres par semaine ([source](https://www.insee.fr/fr/statistiques/4319377#graphique-figure2))","suggestions":{"nulle":0,"ponctuelle":1,"quotidienne":3}}'::jsonb,24,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('alimentation . déchets . quantité jetée','alimentation','Comment estimeriez-vous la quantité de déchets que vous jetez ?','🗑️','CHOIX_UNIQUE','{"options":["base","réduction","zéro déchet"],"defaultValue":"''réduction''","description":"Répondez ''Zéro Déchet'' uniquement si vous traquez le moindre déchet et ne sortez (quasiment) jamais vos poubelles, et \"je limite\" sinon (nous vous questionnerons alors sur les actions que vous avez mises en œuvre).\n"}'::jsonb,25,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('transport . voiture . gabarit','transport','Quel est le gabarit de la voiture ?','🚙','CHOIX_UNIQUE','{"options":["petite","moyenne","VUL","berline","SUV"],"defaultValue":"''VUL''","description":"**💡 Si vous utilisez plusieurs voitures (par exemple dans le cas où vous n''en possédez pas une), choisissez la réponse la plus représentative de votre usage.**\n","note":"Nous considérons que la voiture par défaut est une \"Berline\", en témoigne [une étude menée par AAA Data](https://www.alphabet.com/fr-fr/parc-automobile-roulant-les-donnees-cles)\nqui indique que \"Si les SUV ont représenté 38 % des ventes de véhicules en 2019, ils ne représentent que 16 % de la totalité des véhicules en circulation, loin derrière les berlines qui comptent pour 58 %, soit 23 millions de véhicules.\"\n","dependances":[{"key":"transport . voiture . utilisateur","value":["propriétaire","régulier non propriétaire"],"type":"IN"}]}'::jsonb,26,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('transport . voiture . thermique . carburant','transport','Quel type de carburant votre voiture consomme-t-elle ?','⛽','CHOIX_UNIQUE','{"options":["gazole B7 ou B10","essence E5 ou E10","essence E85","GPL"],"defaultValue":"''essence E5 ou E10''","description":"> Attention, si le type de carburant fait varier de façon significative l''empreinte climat au litre, la consommation en litre par 100km elle aussi varie. Veillez à saisir une consommation au litre basée sur votre moyenne réelle.\n","note":"La domination du couple gazole-essence est écrasante [source](https://www.leprogres.fr/magazine-automobile/2021/03/27/quels-sont-les-carburants-les-plus-utilises-dans-votre-commune).\n\nPar contre, parmi les véhicules neufs, l''essence domine aujourd''hui.\n\nLe facteur d''émission associé au biocarburant E85 n''est pas représentatif des conséquences environnementales liées à l''utilisation des biocarburants.\nEn effet, au vu des problématiques liées au changement d''affectation des sols et autres impacts environnementaux liés à la culture du maïs par exemple, les **biocarburants** ne sont pas pris en compte\n(le facteur d''émission de la base carbone étant particulièrement incertain). Voir nos discussions [ici](https://github.com/incubateur-ademe/nosgestesclimat/pull/1324).\n\nLe GPL (Gaz de Pétrole Liquéfiés) est un [résidu de l''extraction du pétrole qui était autrefois brûlé](https://fr.wikipedia.org/wiki/Gaz_de_p%C3%A9trole_liqu%C3%A9fi%C3%A9).\nIl a une empreinte carbone par litre moins importante que les véhicules essence ou diesel, par contre sa consommation est légèrement supérieure, ce qui compense légèrement le gain.\nMais si les rejets de CO2e sont au final presque équivalents entre le GPL et les autres carburants, c''est [du côté de l''émission de particules nocives](https://agirpourlatransition.ademe.fr/particuliers/conso/conso-responsable/comment-choisir-voiture-deux-roues-moins-polluant) que le GPL est un bien meilleur élève que les autres carburants thermiques.\n\nPour comprendre les différents types de carburants, [cet article pédagogique](https://www.francetvinfo.fr/economie/automobile/essence/les-carburants-changent-de-nom-a-la-pompe-voici-comment-vous-y-retrouver_2967013.html) est très utile.\n\n[Cet article](https://www.ecologie.gouv.fr/carburants-et-combustibles-autorises-en-france) du ministère de l''Écologie explique plus en détail les carburants légaux en France.\n","dependances":[{"key":"transport . voiture . motorisation","value":"thermique","type":"EQUAL"}]}'::jsonb,27,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('divers . animaux domestiques . empreinte','divers','Combien d''animaux vivent avec vous, au sein de votre foyer ?','🐶','COMPTEUR','{"options":["petit chien . nombre","chien moyen . nombre","gros chien . nombre","chats . nombre","aucun . présent"],"description":"Les petits animaux (hamsters, canaris…) ne sont pas pris en compte, car leur empreinte est négligeable. Quant aux animaux de basse-cour comme les poules, leur faible impact est compensé par d''autres bénéfices.\n"}'::jsonb,28,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('divers . loisirs . culture','divers','Quelles sont vos pratiques culturelles ?','🎭','CHOIX_MULTIPLE','{"options":["concerts et spectacles . présent","musées et monuments . présent","édition . présent","pratique de la musique . présent","aucun . présent"]}'::jsonb,29,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('divers . loisirs . sports','divers','Quels sont les sports que vous pratiquez régulièrement ?','⚽','CHOIX_MULTIPLE','{"options":["individuel extérieur . présent","balle ou ballon . présent","aquatique . présent","salle de sport . présent","martial ou combat . présent","athlétisme . présent","équitation . présent","golf . présent","nautique . présent","hiver montagne . présent","sports énergivores . présent","autres sports . présent","aucun . présent"],"note":"La notion de régularité est volontairement imprécise, car elle dépend des sports pratiqués ainsi que du niveau du sportif.\n\nAinsi, on pourra estimer que faire de la voile une fois par mois est une pratique régulière, alors que faire un footing par mois est une pratique anecdotique.\n\nÉgalement, un sportif \"engagé\" considérera qu''une pratique régulière implique plusieurs entraînements par semaine, quand un sportif plus amateur placera peut-être la barre un peu plus bas.\n"}'::jsonb,30,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('divers . numérique . appareils . renouvellement téléphone','divers','En 5 ans, combien de fois avez-vous changé de téléphone ?','📱','CHOIX_UNIQUE','{"options":["faible","moyen","élevé"],"defaultValue":"''moyen''","description":"Indiquez la fréquence de renouvellement de votre téléphone. Cette information nous aide à mieux estimer l''empreinte de vos appareils numériques.\n","note":"La durée de vie d''un smartphone est de 2,5 ans environ selon les dernières données ADEME.\nPour le moment, nous ne posons pas de question sur le caractère reconditionné de ses appareils, faute de données notamment.\n"}'::jsonb,31,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
INSERT INTO public.question_bilan (slug,categorie_empreinte,question,icone,type_widget,config_json,ordre_affichage,est_obligatoire) VALUES ('divers . tabac . consommation par semaine','divers','Quelle est votre consommation par semaine de tabac ?','🚬','NOMBRE','{"min":0,"max":21,"defaultValue":0.5,"unit":"paquet/semaine","description":"💡 Renseignez ici votre consommation de paquets de cigarettes par semaine. On considère qu''un paquet contient 20 cigarettes.\nSi vous fumez des roulées, pensez à adapter votre calcul.\n\n> La cigarette électronique n''est pas encore prise en compte dans nos calculs, faute de données !\n","note":"D''après l''étude INSEE sur les [dépenses des ménages en 2017](https://www.insee.fr/fr/statistiques/4648319?sommaire=4648339), un ménage dépense en moyenne 402€ par an pour l''achat de tabac (tous ménages confondus).\nLe prix d''un paquet de cigarettes en 2017 était de [7,05 euros en moyenne](https://www.toutsurmesfinances.com/argent/a/prix-du-tabac-2017-2018-en-france-historique-et-augmentation).\nPour un ménage de 2,2 personnes (moyenne française), et à raison de 20 cigarettes par paquet, un Français moyen consomme donc environ 520 cigarettes par an, soit 26 paquets par an, soit un demi-paquet par semaine !\n\n> Autre source de données: d''après [Santé Publique France](https://www.santepubliquefrance.fr/determinants-de-sante/tabac/donnees/#tabs),\nun fumeur consomme en moyenne 12,7 cigarettes par jour, soit 4636 cigarettes par jour, ce qui est équivalent à 65 kgCO2e par an. Néanmoins, ce chiffre n''est pas pris en compte dans le calcul.\n\nAvec les hypothèses présentées en début de paragraphe, on attribue une moyenne de 7 kgCO2e environ à chacun des Français.\n","suggestions":{"❌ Je ne fume jamais":0,"1 paquet / semaine":1,"3 paquets / semaine":3}}'::jsonb,32,false) ON CONFLICT(slug) DO UPDATE SET categorie_empreinte=EXCLUDED.categorie_empreinte,question=EXCLUDED.question,icone=EXCLUDED.icone,type_widget=EXCLUDED.type_widget,config_json=EXCLUDED.config_json,ordre_affichage=EXCLUDED.ordre_affichage,est_obligatoire=EXCLUDED.est_obligatoire;
